<template>
	<div class="flex min-h-dvh flex-col bg-gray-50">
		<!-- ============ HEADER ============ -->
		<div
			class="sticky top-0 z-30 border-b border-gray-200 bg-white px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'Home' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-[#2f6bff] transition-colors hover:bg-blue-50 active:bg-blue-100"
					title="Kembali ke Home"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<span class="min-w-0 flex-1 truncate font-medium text-gray-900"
					>Master Karyawan</span
				>
				<span
					v-if="!loading"
					class="shrink-0 rounded-full bg-gray-100 px-2.5 py-0.5 text-xs font-medium text-gray-500"
				>
					{{ rows.length }}{{ hasMore ? '+' : '' }} data
				</span>
			</div>

			<!-- Pencarian + filter status -->
			<div class="mt-3 space-y-2">
				<div class="relative">
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="pointer-events-none absolute left-3 top-1/2 h-5 w-5 -translate-y-1/2 text-gray-400"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<circle cx="11" cy="11" r="7" />
						<path d="m21 21-4.3-4.3" />
					</svg>
					<input
						v-model="search"
						type="search"
						inputmode="search"
						placeholder="Cari nama, ID, atau NIK…"
						class="w-full rounded-xl border border-gray-200 bg-gray-50 py-2.5 pl-10 pr-3 text-base text-gray-900 placeholder:text-gray-400 focus:border-[#2f6bff] focus:bg-white focus:outline-none"
						@keyup.enter="reload"
					/>
				</div>

				<div class="scrollbar-hide -mx-1 flex gap-1.5 overflow-x-auto px-1">
					<button
						v-for="opt in statusOptions"
						:key="opt || 'all'"
						type="button"
						class="shrink-0 rounded-full border px-3 py-1 text-sm font-medium transition"
						:class="
							statusFilter === opt
								? 'border-[#2f6bff] bg-blue-50 text-[#2f6bff]'
								: 'border-gray-200 bg-white text-gray-600 hover:bg-gray-50'
						"
						@click="setStatus(opt)"
					>
						{{ opt || 'Semua' }}
					</button>
				</div>
			</div>
		</div>

		<!-- ============ KONTEN ============ -->
		<div class="app-container-narrow flex-1 px-4 py-4 md:px-6">
			<pre v-if="error" class="whitespace-pre-wrap py-4 text-sm text-red-600">{{
				error
			}}</pre>

			<p v-else-if="loading && !rows.length" class="py-6 text-sm text-gray-500">
				Loading...
			</p>

			<p v-else-if="!rows.length" class="py-10 text-center text-sm text-gray-400">
				Tidak ada karyawan yang cocok.
			</p>

			<div v-else class="space-y-2.5">
				<button
					v-for="row in rows"
					:key="row.name"
					type="button"
					class="flex w-full items-center gap-3 rounded-2xl border border-gray-100 bg-white p-4 text-left shadow-sm transition hover:bg-gray-50 active:bg-gray-100"
					@click="goToDetail(row.name)"
				>
					<img
						v-if="row.image"
						:src="row.image"
						:alt="row.employee_name"
						class="h-11 w-11 shrink-0 rounded-full border border-gray-200 object-cover"
					/>
					<span
						v-else
						class="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-primary/10 text-base font-semibold text-primary"
					>
						{{ initials(row.employee_name || row.name) }}
					</span>

					<span class="min-w-0 flex-1">
						<span class="block truncate text-base font-semibold text-gray-900">
							{{ row.employee_name || row.name }}
						</span>
						<span class="block truncate text-sm text-gray-500">{{
							subtitle(row)
						}}</span>
					</span>

					<span
						v-if="row.status"
						class="shrink-0 rounded-full px-2.5 py-0.5 text-sm font-medium"
						:class="statusPill(row.status)"
					>
						{{ row.status }}
					</span>
				</button>

				<button
					v-if="hasMore"
					type="button"
					class="w-full rounded-xl border border-gray-200 bg-white py-3 text-base font-medium text-[#2f6bff] transition hover:bg-blue-50 disabled:opacity-60"
					:disabled="loading"
					@click="loadMore"
				>
					{{ loading ? 'Memuat…' : 'Muat lebih banyak' }}
				</button>
			</div>
		</div>
	</div>
</template>

<script setup>
/**
 * Daftar Master Karyawan (read-only).
 *
 * Kolom kartu mengikuti field yang ditandai `in_list_view` di doctype — sama
 * dengan yang dipakai list view desk — jadi kalau HR mengubah field mana yang
 * tampil di list, app ikut berubah tanpa ubah kode. Nama, foto, dan status
 * dipakai sebagai kerangka kartu dan selalu diambil.
 *
 * Akses murni mengikuti permission doctype: query lewat `frappe.client.get_list`
 * tanpa ignore_permissions, sehingga user hanya melihat yang memang boleh
 * dilihatnya.
 */
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'

const DOCTYPE = 'Master Karyawan'
const router = useRouter()

function goToDetail(name) {
	router.push({ name: 'MasterKaryawanDetail', params: { name } })
}

// Kerangka kartu — selalu diambil, di luar field in_list_view dari meta.
const BASE_FIELDS = ['name', 'employee_name', 'status', 'image']
// Field yang tidak layak jadi baris subtitle walau in_list_view (sudah jadi
// bagian kerangka kartu, atau terlalu sensitif untuk dipajang di daftar).
const SUBTITLE_SKIP = ['name', 'employee_name', 'image', 'status', 'first_name']

const metaListFields = ref([])
const statusOptions = ref([''])

const listFields = computed(() => [
	...new Set([...BASE_FIELDS, ...metaListFields.value.map((f) => f.fieldname)]),
])

function initials(v) {
	return String(v || '?')
		.trim()
		.split(/\s+/)
		.slice(0, 2)
		.map((w) => w[0])
		.join('')
		.toUpperCase()
}

const STATUS_PILL = {
	Active: 'bg-green-100 text-green-700',
	Inactive: 'bg-gray-100 text-gray-600',
	Suspended: 'bg-amber-100 text-amber-700',
	Left: 'bg-red-100 text-red-700',
}
function statusPill(s) {
	return STATUS_PILL[s] || 'bg-gray-100 text-gray-600'
}

function formatDate(v) {
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}
// Subtitle = gabungan field in_list_view yang terisi, dipisah titik tengah.
function subtitle(row) {
	const parts = metaListFields.value
		.filter((f) => !SUBTITLE_SKIP.includes(f.fieldname))
		.map((f) => {
			const v = row[f.fieldname]
			if (v == null || v === '') return ''
			return ['Date', 'Datetime'].includes(f.fieldtype) ? formatDate(v) : String(v)
		})
		.filter(Boolean)
	return parts.length ? parts.join(' · ') : row.name
}

// ---- Data & pagination -----------------------------------------------------
const pageLength = ref(20)
const start = ref(0)
const rows = ref([])
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')
const search = ref('')
const statusFilter = ref('')

// Status → filter AND biasa. Kata kunci → OR ke nama/ID/NIK lewat `or_filters`
// (frappe.client.get_list menerimanya), supaya satu kotak cari bisa menjangkau
// ketiganya sekaligus.
function buildFilters() {
	const arr = []
	if (statusFilter.value) arr.push(['status', '=', statusFilter.value])
	return arr
}
function buildOrFilters() {
	const q = search.value.trim()
	if (!q) return []
	return [
		['employee_name', 'like', `%${q}%`],
		['name', 'like', `%${q}%`],
		['nik', 'like', `%${q}%`],
	]
}

const list = createResource({
	url: 'frappe.client.get_list',
	makeParams() {
		const params = {
			doctype: DOCTYPE,
			fields: JSON.stringify(listFields.value),
			order_by: 'modified desc',
			limit_start: start.value,
			limit_page_length: pageLength.value,
		}
		const f = buildFilters()
		if (f.length) params.filters = JSON.stringify(f)
		const orF = buildOrFilters()
		if (orF.length) params.or_filters = JSON.stringify(orF)
		return params
	},
	auto: false,
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === pageLength.value
		loading.value = false
	},
	onError(err) {
		error.value = err?.message || String(err)
		loading.value = false
	},
})

function reload() {
	error.value = ''
	start.value = 0
	loading.value = true
	list.fetch()
}
function loadMore() {
	start.value += pageLength.value
	loading.value = true
	list.fetch()
}
function setStatus(opt) {
	statusFilter.value = opt
	reload()
}

// ---- Meta: field list view + opsi status -----------------------------------
async function loadMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(DOCTYPE)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const meta = docs.find((x) => x.name === DOCTYPE) || docs[0]
		const fields = (meta && meta.fields) || []
		metaListFields.value = fields.filter((f) => f.in_list_view && !f.hidden)
		// Opsi filter status ikut opsi field `status` di doctype.
		const statusField = fields.find((f) => f.fieldname === 'status')
		if (statusField?.options) {
			statusOptions.value = ['', ...statusField.options.split('\n').filter(Boolean)]
		}
	} catch (e) {
		/* meta gagal → kartu tetap tampil dengan kerangka dasar */
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	await loadMeta()
	reload()
})
</script>
