<template>
	<div>
		<!-- Skeleton saat memuat -->
		<div v-if="loading && !stats" class="flex gap-3">
			<div
				class="h-[5.5rem] basis-[82%] shrink-0 rounded-[1.5rem] bg-black/5 animate-pulse"
			/>
			<div
				class="h-[5.5rem] basis-[82%] shrink-0 rounded-[1.5rem] bg-black/5 animate-pulse"
			/>
		</div>

		<div
			v-else-if="error"
			class="rounded-[1.5rem] bg-white px-5 py-4 text-sm font-medium text-slate-400 shadow-sm"
		>
			Gagal memuat ringkasan.
		</div>

		<template v-else>
			<!-- Track: horizontal scroll + snap (swipe manual). Kartu mengintip → jelas bisa digeser. -->
			<div
				ref="track"
				@scroll.passive="onScroll"
				class="flex gap-3 overflow-x-auto snap-x snap-mandatory scrollbar-hide"
			>
				<div
					v-for="(card, i) in cards"
					:key="i"
					class="snap-start shrink-0 basis-[82%] sm:basis-[46%]"
				>
					<!-- Kartu angka tunggal -->
					<div
						v-if="card.type === 'count'"
						class="h-full rounded-[1.5rem] bg-white px-5 py-4 shadow-sm"
					>
						<p class="text-sm font-semibold text-slate-500">{{ card.label }}</p>
						<p class="mt-1.5 text-4xl font-extrabold leading-none text-[#2f6bff]">
							{{ fmtInt(card.value) }}
						</p>
						<p class="mt-2.5 text-xs text-slate-400">{{ card.unit || 'dokumen' }}</p>
					</div>

					<!-- Kartu ganda Unit | Amount (pemisah vertikal di tengah) -->
					<div v-else class="h-full rounded-[1.5rem] bg-white px-5 py-4 shadow-sm">
						<p class="truncate text-sm font-semibold text-slate-500">
							{{ card.label }}
						</p>
						<div class="mt-2 flex items-stretch">
							<div class="min-w-0 flex-1 pr-3">
								<p class="text-xs font-medium text-slate-400">Unit</p>
								<p
									class="mt-1 truncate text-2xl font-extrabold leading-none text-[#2f6bff]"
								>
									{{ fmtInt(card.unit) }}
								</p>
							</div>
							<div class="w-px self-stretch bg-slate-200"></div>
							<div class="min-w-0 flex-1 pl-3">
								<p class="text-xs font-medium text-slate-400">Amount</p>
								<p
									class="mt-1 truncate text-2xl font-extrabold leading-none text-[#2f6bff]"
									:title="fmtFull(card.amount)"
								>
									{{ fmtCompact(card.amount) }}
								</p>
							</div>
						</div>
					</div>
				</div>
			</div>

			<!-- Indikator titik -->
			<div class="mt-3 flex justify-center gap-1.5">
				<button
					v-for="(card, i) in cards"
					:key="i"
					type="button"
					:aria-label="`Ke kartu ${i + 1}`"
					@click="goTo(i)"
					:class="[
						'h-1.5 rounded-full transition-all duration-300',
						i === active ? 'w-5 bg-[#2f6bff]' : 'w-1.5 bg-white',
					]"
				/>
			</div>
		</template>
	</div>
</template>

<script setup>
import { computed, ref, onMounted, onBeforeUnmount } from 'vue'
import { createResource } from 'frappe-ui'

// Endpoint ringkasan. Dua bentuk data sesuai `variant`:
//  - 'pengajuan' (default): register/proses_ca/proses_banding/
//    dalam_proses_pencairan{unit,amount}/sudah_pencairan{unit,amount}.
//    Pimcab → get_pimcab_stats (scope cabang); CMO → get_cmo_stats (scope marketing).
//  - 'collection': total/gagal_bayar/partial/tarikan/done (count akun) dari
//    get_coll_stats untuk role *Coll*.
const props = defineProps({
	url: { type: String, required: true },
	variant: { type: String, default: 'pengajuan' },
})

// Resource disimpan di scope MODUL (bertahan selama SPA hidup), di-cache per-url.
// Saat user kembali ke Home, komponen mount ulang tapi resource + datanya dipakai
// kembali → tidak fetch ulang, tidak ada flash skeleton. Fetch hanya sekali per url.
const resourceByUrl = new Map()
function getStatsResource(url) {
	if (!resourceByUrl.has(url)) {
		// Hidrasi dari localStorage → data terakhir tampil INSTAN saat pertama buka
		// (tanpa skeleton), lalu divalidasi ulang oleh fetch. Skeleton hanya muncul
		// sekali seumur hidup (saat benar-benar belum ada cache sama sekali).
		const cacheKey = 'homeStats:' + url
		let initialData
		try {
			const raw = localStorage.getItem(cacheKey)
			if (raw) initialData = JSON.parse(raw)
		} catch {}

		resourceByUrl.set(
			url,
			createResource({
				url,
				method: 'GET',
				auto: true,
				initialData,
				onSuccess(data) {
					try {
						localStorage.setItem(cacheKey, JSON.stringify(data))
					} catch {}
				},
			})
		)
	}
	return resourceByUrl.get(url)
}

const statsRes = getStatsResource(props.url)
const stats = computed(() => statsRes.data)
const loading = computed(() => statsRes.loading)
const error = computed(() => statsRes.error)

// Stale-while-revalidate: data lama tetap tampil (tanpa skeleton) sementara fetch
// berjalan di latar belakang. reload() TIDAK mengosongkan data, jadi skeleton hanya
// muncul saat memang belum ada data sama sekali (load pertama seumur sesi).
let pollTimer = null
onMounted(() => {
	// Refresh diam-diam tiap kali Home dibuka (kalau sudah pernah ada data).
	if (statsRes.data) statsRes.reload()
	// Polling berkala agar angka tetap ~realtime selama halaman terbuka.
	pollTimer = setInterval(() => statsRes.reload(), 30000)
})
onBeforeUnmount(() => {
	if (pollTimer) clearInterval(pollTimer)
})

// Refresh manual dari luar (tombol di section home). reload() tidak mengosongkan
// data → hanya angka di kartu yang diperbarui, tanpa skeleton & tanpa reload halaman.
function reload() {
	return statsRes.reload()
}
defineExpose({ reload })

// Lima kartu. Bentuk kartu mengikuti `variant`.
const cards = computed(() => {
	const s = stats.value
	if (!s) return []

	// Collection: 5 kartu count akun (Total + per status Target dan Realisasi).
	if (props.variant === 'collection') {
		return [
			{ type: 'count', label: 'Total', value: s.total, unit: 'akun' },
			{ type: 'count', label: 'Gagal Bayar', value: s.gagal_bayar, unit: 'akun' },
			{ type: 'count', label: 'Partial', value: s.partial, unit: 'akun' },
			{ type: 'count', label: 'Tarikan', value: s.tarikan, unit: 'akun' },
			{ type: 'count', label: 'Done', value: s.done, unit: 'akun' },
		]
	}

	// Pengajuan (CMO/Pimcab): label & struktur identik, hanya datanya beda.
	return [
		{ type: 'count', label: 'Register', value: s.register },
		{ type: 'count', label: 'Proses CA', value: s.proses_ca },
		{ type: 'count', label: 'Proses Banding', value: s.proses_banding },
		{
			type: 'dual',
			label: 'Dalam Proses Pencairan',
			unit: s.dalam_proses_pencairan?.unit,
			amount: s.dalam_proses_pencairan?.amount,
		},
		{
			type: 'dual',
			label: 'Sudah Pencairan',
			unit: s.sudah_pencairan?.unit,
			amount: s.sudah_pencairan?.amount,
		},
	]
})

// ---- Format angka ----------------------------------------------------------
function fmtInt(v) {
	return (Number(v) || 0).toLocaleString('id-ID')
}
function fmtFull(v) {
	return 'Rp ' + (Number(v) || 0).toLocaleString('id-ID')
}
// Ringkas agar muat di kartu: ≥1 M / ≥1 jt / ≥1 rb. Nilai penuh ada di tooltip.
function fmtCompact(v) {
	const n = Number(v) || 0
	if (n >= 1e9)
		return 'Rp ' + (n / 1e9).toLocaleString('id-ID', { maximumFractionDigits: 1 }) + ' M'
	if (n >= 1e6)
		return 'Rp ' + (n / 1e6).toLocaleString('id-ID', { maximumFractionDigits: 1 }) + ' jt'
	if (n >= 1e3)
		return 'Rp ' + (n / 1e3).toLocaleString('id-ID', { maximumFractionDigits: 0 }) + ' rb'
	return 'Rp ' + n.toLocaleString('id-ID')
}

// ---- Carousel (snap + dots) ------------------------------------------------
const track = ref(null)
const active = ref(0)
function onScroll() {
	const el = track.value
	if (!el) return
	const center = el.scrollLeft + el.clientWidth / 2
	let best = 0
	let bestDist = Infinity
	;[...el.children].forEach((child, i) => {
		const childCenter = child.offsetLeft + child.offsetWidth / 2
		const dist = Math.abs(childCenter - center)
		if (dist < bestDist) {
			bestDist = dist
			best = i
		}
	})
	active.value = best
}
function goTo(i) {
	const el = track.value
	if (!el) return
	const child = el.children[i]
	if (child) child.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' })
}
</script>
