<script setup>
import { computed, ref } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { createResource } from 'frappe-ui'
import TodoIcon from './TodoIcon.vue'
import { useRoleMenu } from '../composables/useRoleMenu'
import { isNativeApp, openInAppBrowser } from '../data/mobile'
import { notifyError } from '../composables/toast'

const router = useRouter()
const route = useRoute()
const { department } = useRoleMenu()

// Pop-up menu aksi dari FAB tengah.
const menuOpen = ref(false)

// CekUnit adalah SPA terpisah (/cekunit/) yang butuh sesi cookie. Di bundel
// lokal native, origin app = https://localhost, jadi navigasi <a> ke /cekunit/
// menuju path lokal yang tak ada → layar putih. Solusinya: minta token login
// sekali-pakai (desk_bridge) lalu buka URL-nya di in-app browser dgn sesi valid.
// Di web: biarkan <a href="/cekunit/"> menavigasi normal (same-origin).
const cekUnitTokenRes = createResource({
	url: 'juragan.api.portal.desk_bridge.create_desk_login_token',
	method: 'POST',
})
async function openCekUnit(e) {
	if (!isNativeApp()) return
	e.preventDefault()
	menuOpen.value = false
	try {
		const res = await cekUnitTokenRes.submit({ redirect: '/cekunit/' })
		await openInAppBrowser(res.url)
	} catch (err) {
		notifyError(err, 'Gagal membuka Cek Unit')
	}
}
function toggleMenu() {
	menuOpen.value = !menuOpen.value
}
function closeMenu() {
	menuOpen.value = false
}

// Item ke-1 (Cek Unit) selalu tampil (dirender khusus sbg <a> ke /cekunit/).
// Aksi lain di pop-up dibedakan per role:
//  - CMO (marketing) : Create Data Pengajuan
//  - Pimcab          : tidak ada (hanya Cek Unit)
//  - lainnya (admin) : Create Data Pengajuan
const ACTION_CREATE_DP = {
	name: 'DataPengajuan',
	label: 'Create Data Pengajuan',
	route: 'DataPengajuanCreate',
}
const actions = computed(() => (department.value?.key === 'pimcab' ? [] : [ACTION_CREATE_DP]))

// Tutup modal; bila item punya `route`, navigasi ke sana (mis. Create Data
// Pengajuan → DataPengajuanCreate = /portal/data-pengajuan/new).
function selectAction(a) {
	menuOpen.value = false
	if (a.route) router.push({ name: a.route })
}

function go(name) {
	if (route.name !== name) router.push({ name })
}

function isActive(name) {
	return route.name === name
}
</script>

