// HARUS paling atas: memasang polyfill (mis. Promise.withResolvers untuk PDF.js)
// sebelum modul lain dievaluasi.
import './polyfills'
// Shim fetch (mode native/bundel lokal): arahkan request ke backend produksi +
// header token. Harus sebelum modul yang bisa memicu request.
import './data/fetchShim'

import { initPush, pushLogin } from './data/push'
import { initNativeBack } from './data/nativeBack'
import { initNativeLinks } from './data/nativeLinks'
import { sessionUser, session } from './data/session'
import { isNativeApp } from './data/mobile'
import './index.css'

import { createApp } from 'vue'
import router from './router'
import App from './App.vue'

import { Button, setConfig, frappeRequest, resourcesPlugin } from 'frappe-ui'
import { notifyError } from './composables/toast'

// `import.meta.env.VITE_FRAPPE_DEV_SITE` di-inject Vite dari
// common_site_config.json. Di production string kosong → fallback ke
// frappeRequest default (baca site dari window.location.hostname).
const devSiteName = import.meta.env.VITE_FRAPPE_DEV_SITE || ''
const isDev = import.meta.env.DEV

// Endpoint/aksi yang error-nya SENGAJA ditangani sendiri oleh pemanggil (mis.
// cek sesi login) → jangan munculkan toast global otomatis untuk ini.
const SILENT_ERROR_URLS = ['login', 'logout', 'frappe.auth.get_logged_user']

function shouldNotify(options, err) {
	// Saat offline, layar "Tidak Ada Koneksi" sudah menjelaskan — jangan spam toast.
	if (typeof navigator !== 'undefined' && navigator.onLine === false) return false
	const url = String(options?.url || '')
	if (SILENT_ERROR_URLS.some((u) => url.includes(u))) return false
	// Belum login (session expired) → biarkan route guard menangani, jangan spam.
	const code = err?.httpStatus || err?.status
	if (code === 403 && !session.isLoggedIn) return false
	return true
}

function siteAwareFetcher(options = {}) {
	const req =
		!isDev || !devSiteName
			? frappeRequest(options)
			: frappeRequest({
					...options,
					headers: {
						'X-Frappe-Site-Name': devSiteName,
						...(options.headers || {}),
					},
			  })
	// Setiap request frappe-ui (createResource) yang gagal → notifikasi global
	// otomatis, lalu error tetap dilempar agar penanganan lokal tetap jalan.
	return req.catch((err) => {
		try {
			if (shouldNotify(options, err)) notifyError(err, 'Gagal memuat data')
		} catch (e) {
			/* jangan sampai handler notifikasi menelan error asli */
		}
		throw err
	})
}

setConfig('resourceFetcher', siteAwareFetcher)

const app = createApp(App)

// Error render/komponen Vue yang tidak tertangkap → notifikasi + log.
app.config.errorHandler = (err, instance, info) => {
	notifyError(err, 'Terjadi kesalahan')
	// eslint-disable-next-line no-console
	console.error('[vue errorHandler]', info, err)
}

// Saat offline, biarkan layar "Tidak Ada Koneksi" yang bicara — jangan toast.
function isOffline() {
	return typeof navigator !== 'undefined' && navigator.onLine === false
}
// Promise rejection & error global (di luar Vue) → notifikasi.
window.addEventListener('unhandledrejection', (event) => {
	if (isOffline()) return
	notifyError(event.reason, 'Terjadi kesalahan')
})
window.addEventListener('error', (event) => {
	// Abaikan error pemuatan resource (img/script) — hanya error runtime JS.
	if (isOffline()) return
	if (event.error) notifyError(event.error, 'Terjadi kesalahan')
})

app.use(router)
app.use(resourcesPlugin)
app.component('Button', Button)
app.mount('#app')

// Hapus splash boot (C3) setelah SPA ter-mount.
const bootSplash = document.getElementById('boot-splash')
if (bootSplash) bootSplash.remove()

initPush(router)
initNativeBack()
initNativeLinks()

const pushUser = sessionUser()
if (pushUser) pushLogin(pushUser)

// Register Service Worker (PWA) — hanya di production web. Di native (bundel
// lokal) dilewati: WKWebView iOS tidak mendukung SW, dan cache SW bisa membuat
// konten basi di dalam app.
if ('serviceWorker' in navigator && import.meta.env.PROD && !isNativeApp()) {
	window.addEventListener('load', () => {
		navigator.serviceWorker
			.register(`${import.meta.env.BASE_URL}sw.js`, {
				scope: import.meta.env.BASE_URL,
			})
			.catch((err) => console.warn('SW registration gagal:', err))
	})
} else if ('serviceWorker' in navigator && import.meta.env.DEV) {
	navigator.serviceWorker.getRegistrations().then((regs) => {
		for (const reg of regs) reg.unregister()
	})
}
