</template>

<script setup>
import { computed, h, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { refreshCsrfToken } from '../data/session'
import { currentUser } from '../data/user'
import { notifyError, notifySuccess } from '../composables/toast'
import MentionInput from '../components/MentionInput.vue'

const route = useRoute()
const name = route.params.name

// Tab: Detail (hasil ekstraksi) & Comments (doctype Comment, seperti Data Pengajuan).
const TABS = [
	{
		key: 'detail',
		label: 'Detail',
		icon: '<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/>',
	},
	{
		key: 'comments',
		label: 'Comments',
		icon: '<path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/>',
	},
]
const activeTab = ref('detail')

const doc = ref(null)
const loading = ref(true)
const loadError = ref('')
const busy = ref(false)
const extracting = ref(false)

// Field hasil ekstraksi yang boleh dikoreksi manusia saat status "Perlu Review".
// Cerminan doctype: label_referensi_terbaca/catatan_validasi/image_hash/raw_response
// read_only, data nasabah ikut fetch_from → tidak diedit dari sini.
const EDITABLE_FIELDS = [
	'nomor_referensi',
	'nominal',
	'metode',
	'tanggal_transaksi',
	'waktu_transaksi',
	'status_transaksi',
	'nama_pengirim',
	'rekening_pengirim',
	'nama_penerima',
	'rekening_penerima',
]
// Sama dengan opsi Select `metode` di doctype Resi.
const METODE_OPTIONS = [
	'BCA',
	'Mandiri',
	'BRI',
	'BNI',
	'BSI',
	'CIMB',
	'Permata',
	'SeaBank',
	'DANA',
	'OVO',
	'GoPay',
	'ShopeePay',
	'LinkAja',
	'QRIS',
	'Lainnya',
]
const form = reactive(Object.fromEntries(EDITABLE_FIELDS.map((f) => [f, ''])))

// Boleh diedit HANYA saat "Perlu Review". Begitu "Selesai" dokumen terkunci.
const editable = computed(() => doc.value?.status === 'Perlu Review')
// Aksi disembunyikan total saat "Selesai" (terkunci) dan "Diproses" (sedang jalan).
const showActions = computed(
	() =>
		!!doc.value &&
		activeTab.value === 'detail' &&
		!['Selesai', 'Diproses'].includes(doc.value.status)
)

const labelClass = 'mb-1 block text-xs font-medium text-gray-500'
const inputClass =
	'min-h-[44px] w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

// Baris info kecil (dl). Read-only, cermin field doctype.
const InfoRow = (props) =>
	h('div', { class: 'flex items-start justify-between gap-3' }, [
		h('dt', { class: 'shrink-0 text-sm text-gray-500' }, props.label),
		h(
			'dd',
			{
				class: [
					'min-w-0 break-words text-right text-sm',
					props.strong ? 'font-semibold text-gray-900' : 'font-medium text-gray-800',
				],
			},
			props.value ? String(props.value) : '—'
		),
	])
InfoRow.props = ['label', 'value', 'strong']

// ---- Peta warna status (cermin desk) --------------------------------------
const STATUS_STYLE = {
	Draft: {
		wrap: 'border-gray-200 bg-gray-50 text-gray-700',
		badge: 'bg-gray-200 text-gray-700',
	},
	Diproses: {
		wrap: 'border-blue-200 bg-blue-50 text-blue-800',
		badge: 'bg-blue-100 text-blue-700',
	},
	'Perlu Review': {
		wrap: 'border-orange-200 bg-orange-50 text-orange-800',
		badge: 'bg-orange-100 text-orange-700',
	},
	Selesai: {
		wrap: 'border-green-200 bg-green-50 text-green-800',
		badge: 'bg-green-100 text-green-700',
	},
	Gagal: { wrap: 'border-red-200 bg-red-50 text-red-800', badge: 'bg-red-100 text-red-700' },
	Duplikat: { wrap: 'border-red-200 bg-red-50 text-red-800', badge: 'bg-red-100 text-red-700' },
}
const statusBanner = computed(() => STATUS_STYLE[doc.value?.status] || STATUS_STYLE.Draft)

// ---- Peringatan field kosong (label ramah, cermin desk) -------------------
const LABEL_CEK = {
	nomor_referensi: 'No Referensi',
	nominal: 'Nominal',
	tanggal_transaksi: 'Tanggal',
	nama_pengirim: 'Nama Pengirim',
	rekening_pengirim: 'Rekening Pengirim',
	nama_penerima: 'Nama Penerima',
	rekening_penerima: 'Rekening Penerima',
}
const emptyNote = computed(() => {
	const d = doc.value
	if (!d || !d.status || d.status === 'Draft' || d.status === 'Diproses') return ''
	const kosong = Object.keys(LABEL_CEK)
		.filter((f) => !d[f])
		.map((f) => `${LABEL_CEK[f]} Kosong`)
	return kosong.length ? kosong.join(', ') : ''
})

// ---- Util -----------------------------------------------------------------
function rupiah(v) {
	if (v == null || v === '') return ''
	return 'Rp ' + Number(v).toLocaleString('id-ID')
}
function tanggal(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}
function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}

// ---- Load -----------------------------------------------------------------
async function load() {
	loading.value = true
	loadError.value = ''
	try {
		const params = new URLSearchParams({ doctype: 'Resi', name: String(name) })
		const res = await fetch(`/api/method/frappe.client.get?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		doc.value = json.message
		// Salin nilai ke form supaya input koreksi mulai dari hasil ekstraksi.
		EDITABLE_FIELDS.forEach((f) => {
			form[f] = doc.value?.[f] ?? ''
		})
	} catch (e) {
		loadError.value = e.message || String(e)
	} finally {
		loading.value = false
	}
}

// ---- Aksi -----------------------------------------------------------------
async function reExtract() {
	busy.value = true
	extracting.value = true
	try {
		await refreshCsrfToken()
		const res = await fetch(
			'/api/method/juragan.juragan.doctype.resi.resi.run_extraction_now',
			{
				method: 'POST',
				credentials: 'include',
				headers: {
					'Content-Type': 'application/json',
					Accept: 'application/json',
					'X-Frappe-CSRF-Token': window.csrf_token || '',
				},
				body: JSON.stringify({ docname: String(name) }),
			}
		)
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		await load()
	} catch (e) {
		notifyError(e, 'Gagal mengekstrak ulang')
	} finally {
		busy.value = false
		extracting.value = false
	}
}

// Kirim beberapa field sekaligus: frappe.client.set_value menerima dict pada
// `fieldname`. Dipakai untuk simpan koreksi (dan sekalian set status Selesai).
async function setValues(payload) {
	await refreshCsrfToken()
	const res = await fetch('/api/method/frappe.client.set_value', {
		method: 'POST',
		credentials: 'include',
		headers: {
			'Content-Type': 'application/json',
			Accept: 'application/json',
			'X-Frappe-CSRF-Token': window.csrf_token || '',
		},
		body: JSON.stringify({
			doctype: 'Resi',
			name: String(name),
			fieldname: payload,
		}),
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
	return json
}

// Nilai form siap kirim: string kosong → null supaya field benar-benar dikosongkan.
function editedPayload() {
	const out = {}
	EDITABLE_FIELDS.forEach((f) => {
		const v = typeof form[f] === 'string' ? form[f].trim() : form[f]
		out[f] = v === '' || v === undefined ? null : v
	})
	return out
}

// Konfirmasi: simpan koreksi + kunci dokumen (status Selesai) dalam satu aksi.
async function confirmSelesai() {
	busy.value = true
	try {
		await setValues({ ...editedPayload(), status: 'Selesai' })
		notifySuccess('Perubahan tersimpan. Resi ditandai Selesai.')
		await load()
	} catch (e) {
		notifyError(e, 'Gagal mengonfirmasi')
	} finally {
		busy.value = false
	}
}

// ---- Comments (doctype Comment) -------------------------------------------
const comments = reactive({
	loading: false,
	error: '',
	items: [],
	showForm: false,
	body: '',
	submitting: false,
})

function initials(nameStr) {
	return String(nameStr)
		.split(/\s+/)
		.filter(Boolean)
		.slice(0, 2)
		.map((w) => w[0]?.toUpperCase() || '')
		.join('')
}

function timeAgo(dateStr) {
	if (!dateStr) return ''
	const then = new Date(String(dateStr).replace(' ', 'T'))
	const sec = Math.floor((Date.now() - then.getTime()) / 1000)
	if (sec < 60) return 'just now'
	const min = Math.floor(sec / 60)
	if (min < 60) return `${min} minute${min > 1 ? 's' : ''} ago`
	const hr = Math.floor(min / 60)
	if (hr < 24) return `${hr} hour${hr > 1 ? 's' : ''} ago`
	const d = Math.floor(hr / 24)
	if (d === 1) return 'yesterday'
	if (d < 7) return `${d} days ago`
	const w = Math.floor(d / 7)
	if (w < 5) return `${w} week${w > 1 ? 's' : ''} ago`
	const mo = Math.floor(d / 30)
	if (mo < 12) return `${mo} month${mo > 1 ? 's' : ''} ago`
	const y = Math.floor(d / 365)
	return `${y} year${y > 1 ? 's' : ''} ago`
}

// List comment dokumen ini (GET, tidak butuh CSRF).
// Pakai endpoint portal (bukan client.get_list Comment): role biasa tak punya
// read permission pada doctype Comment → 403. Endpoint menggerbang lewat izin
// BACA Resi lalu query Comment dgn ignore_permissions.
async function loadComments() {
	comments.loading = true
	comments.error = ''
	try {
		const params = new URLSearchParams({ reference_name: String(name) })
		const res = await fetch(
			`/api/method/juragan.api.portal.resi.get_comments?${params.toString()}`,
			{
				method: 'GET',
				credentials: 'include',
				headers: { Accept: 'application/json' },
			}
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		comments.items = json.message || []
	} catch (e) {
		comments.error = e.message || String(e)
	} finally {
		comments.loading = false
	}
}

// Isi komentar berupa HTML (dari MentionInput). Tombol Kirim aktif kalau ada
// teks setelah tag dibuang — meniru update_state() ControlComment di desk.
function stripHtmlText(html) {
	if (!html) return ''
	const el = document.createElement('div')
	el.innerHTML = html
	return (el.textContent || '').replace(/[\s ﻿]+/g, ' ').trim()
}
const commentHasText = computed(() => !!stripHtmlText(comments.body))

// User "terlibat" di dokumen ini → didahulukan di daftar mention, seperti
// prioritize_involved_users_in_mention di desk (frm.get_involved_users()).
const mentionPriorityUsers = computed(() => {
	const d = doc.value || {}
	const users = [d.owner, d.modified_by]
	try {
		users.push(...JSON.parse(d._assign || '[]'))
	} catch {
		// _assign bukan JSON valid → abaikan
	}
	comments.items.forEach((c) => users.push(c.comment_email || c.owner))
	return [...new Set(users)].filter((u) => u && u !== 'Administrator' && u !== currentUser.user)
})

// Insert comment baru (POST → butuh CSRF token), lalu refresh list.
async function submitComment() {
	const body = comments.body.trim()
	if (!body || !commentHasText.value) return
	comments.submitting = true
	comments.error = ''
	try {
		await refreshCsrfToken()
		// Pakai add_comment (bukan client.insert Comment): izinnya berbasis akses
		// BACA dokumen Resi, bukan izin CREATE doctype Comment — yang hanya
		// dimiliki System Manager/Website Manager → selain itu 403.
		const res = await fetch('/api/method/frappe.desk.form.utils.add_comment', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({
				reference_doctype: 'Resi',
				reference_name: String(name),
				content: body,
				comment_email: currentUser.user,
				comment_by: currentUser.fullName || currentUser.user,
			}),
		})
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		comments.body = ''
		comments.showForm = false
		await loadComments()
	} catch (e) {
		comments.error = e.message || String(e)
		notifyError(e, 'Gagal mengirim komentar')
	} finally {
		comments.submitting = false
	}
}

// Tutup form komentar & kosongkan isinya (tombol Batal).
function cancelComment() {
	comments.showForm = false
	comments.body = ''
}

onMounted(() => {
	load()
	loadComments()
})
</script>
